/bin/bash -lc "find / -type f \\( -name 'pvpython' -o -name 'paraview' -o -name 'ttkPersistenceDiagramCmd' \\) 2>/dev/null | head -30; find / -type f -name 'libttk*' 2>/dev/null | head -20; python3 - <<'PY'
try:
 import paraview
 print('paraview module', paraview.__file__)
except Exception as e: print('no paraview',e)
try:
 import vtk
 print('vtk',vtk.VTK_VERSION)
except Exception as e: print('no vtk', e)
PY"

