try:
 import paraview
 print('paraview module', paraview.__file__)
except Exception as e: print('no paraview',e)
try:
 import vtk
 print('vtk',vtk.VTK_VERSION)
except Exception as e: print('no vtk', e)
PY"

/bin/bash -lc "/opt/conda/bin/pvpython - <<'PY'
from paraview.simple import *
from paraview import servermanager
LoadPlugin('/opt/conda/bin/plugins/TopologyToolKit/TopologyToolKit.so', remote=False, ns=globals())
r=XMLImageDataReader(FileName=['/workspace/QMCPACK.vti'])
s=TTKTopologicalSimplificationByPersistence(Input=r); s.InputArray=['POINTS','Scalars_'];s.PersistenceThreshold=0.04;s.ThresholdIsAbsolute=1
m=TTKMorseSmaleComplex(Input=s);m.ScalarField=['POINTS','Scalars_'];m.ThresholdIsAbsolute=1;m.SaddleConnectorsPersistenceThreshold=0
for port in range(6):
 try:
  UpdatePipeline(proxy=m,outputPort=port); d=servermanager.Fetch(OutputPort(m,port));
  print('port',port,d.GetClassName(),d.GetNumberOfPoints(),d.GetNumberOfCells(),[d.GetPointData().GetArrayName(i) for i in range(d.GetPointData().GetNumberOfArrays())],[d.GetCellData().GetArrayName(i) for i in range(d.GetCellData().GetNumberOfArrays())])
 except Exception as e: print(port,type(e).__name__,str(e)[:100])
PY"

